content:
{
  "role": "adversarial_referee",
  "topic": "Using a swarm (of autonomous agents/sensors) to study cosmic censorship",
  "goal": "Prevent overclaiming support/refutation of cosmic censorship from swarm-based observations or simulations",
  "category_errors": [
    {
      "id": "CE1",
      "name": "Simulation-to-reality conflation",
      "description": "Treating swarm simulation outputs (e.g., agent-based models, numerical relativity surrogates) as direct empirical evidence about the physical universe.",
      "why_invalid": "Cosmic censorship is a mathematical conjecture about solutions to Einstein's field equations under specific energy conditions; simulations instantiate only a measure-zero subset of assumptions and are not observations of astrophysical black holes."
    },
    {
      "id": "CE2",
      "name": "Swarm-as-detector fallacy",
      "description": "Assuming a swarm of drones/agents can directly observe event horizons, singularities, or global causal structure.",
      "why_invalid": "Event horizons and singularities are not locally observable in finite time; global causal structure requires boundary data inaccessible to any finite swarm. Swarms measure local fields, not spacetime topology."
    },
    {
      "id": "CE3",
      "name": "Conjecture-as-hypothesis test",
      "description": "Treating cosmic censorship as a simple falsifiable hypothesis with a binary outcome, rather than a family of conjectures (weak, strong, cosmic censorship) with different formal statements.",
      "why_invalid": "Refuting one formulation (e.g., weak cosmic censorship for a specific matter model) does not refute others; supporting one does not support all."
    },
    {
      "id": "CE4",
      "name": "Scale/regime equivocation",
      "description": "Using swarm behavior at laboratory, terrestrial, or astrophysical scales to infer Planck-scale or singularity-scale physics.",
      "why_invalid": "No known scaling law maps swarm collective dynamics to quantum gravity or horizon-scale phenomena; scale separation is enormous and unjustified."
    },
    {
      "id": "CE5",
      "name": "Analogy-as-evidence",
      "description": "Claiming that swarm self-organization, information loss, or emergent boundaries are 'analogues' of cosmic censorship.",
      "why_invalid": "Analogies can inspire models but do not constitute evidence for or against a mathematical conjecture in general relativity."
    },
    {
      "id": "CE6",
      "name": "Agent-relative ontology",
      "description": "Mistaking swarm-relative observables (what agents can communicate) for observer-independent spacetime properties.",
      "why_invalid": "Cosmic censorship is formulated in a covariant, observer-independent framework; agent-relative data are insufficient unless mapped rigorously to covariant quantities."
    },
    {
      "id": "CE7",
      "name": "Statistical significance vs. physical relevance",
      "description": "Using p-values from swarm experiments/simulations as if they test the conjecture.",
      "why_invalid": "Statistical significance in a model does not address the mathematical or physical validity of the conjecture's assumptions."
    },
    {
      "id": "CE8",
      "name": "Category error of 'refutation'",
      "description": "Claiming a swarm refutes cosmic censorship because it produced a naked singularity in a simulation.",
      "why_invalid": "A numerical naked singularity may be a coordinate artifact, numerical instability, or violation of energy conditions; it is not a physical counterexample unless embedded in a rigorous solution."
    }
  ],
  "false_positives": [
    {
      "id": "FP1",
      "name": "Numerical naked singularity",
      "description": "Simulation shows singularity visible to swarm agents.",
      "likely_cause": "Coordinate singularity, gauge artifact, insufficient resolution, or unphysical initial data.",
      "required_disambiguation": "Convergence tests, invariant diagnostics (Kretschmann scalar), horizon finders, and proof that energy conditions hold."
    },
    {
      "id": "FP2",
      "name": "Swarm consensus on 'no horizon'",
      "description": "Agents report no trapped surface.",
      "likely_cause": "Agents lack global data; trapped surfaces are nonlocal and require boundary/initial data.",
      "required_disambiguation": "Demonstrate that agent measurements can reconstruct apparent horizon or trapped region under explicit assumptions."
    },
    {
      "id": "FP3",
      "name": "Information loss in swarm communication",
      "description": "Swarm loses information across an emergent boundary.",
      "likely_cause": "Finite bandwidth, decoherence, or classical channel limits, not spacetime causality.",
      "required_disambiguation": "Show mapping to quantum information in curved spacetime and rule out classical communication artifacts."
    },
    {
      "id": "FP4",
      "name": "Emergent metric from swarm",
      "description": "Swarm dynamics yields an effective metric with a singularity.",
      "likely_cause": "Analogy or coarse-grained model, not a solution to Einstein's equations.",
      "required_disambiguation": "Derive effective action, show it satisfies Einstein equations or a controlled approximation, and identify matter content."
    },
    {
      "id": "FP5",
      "name": "Statistical anomaly in swarm data",
      "description": "Anomalous clustering interpreted as censorship violation.",
      "likely_cause": "Selection bias, instrumental noise, or model overfitting.",
      "required_disambiguation": "Pre-registered analysis, independent replication, and null tests."
    },
    {
      "id": "FP6",
      "name": "Analogue gravity experiment",
      "description": "Swarm or fluid analogue shows horizon-like behavior.",
      "likely_cause": "Analogue systems test kinematic analogues, not full dynamical gravity.",
      "required_disambiguation": "Explicitly state which conjecture formulation is addressed and why the analogy is faithful."
    },
    {
      "id": "FP7",
      "name": "Swarm 'violates' energy conditions",
      "description": "Effective stress-energy from swarm violates energy conditions.",
      "likely_cause": "Effective description includes non-gravitational forces or coarse-graining artifacts.",
      "required_disambiguation": "Show violation persists in a covariant, closed system with no external forces."
    }
  ],
  "minimum_evidence_needed": {
    "for_support": [
      "A precise formulation of the cosmic censorship conjecture being addressed (weak/strong, matter model, initial data class).",
      "A rigorous mapping from swarm observables to covariant spacetime quantities (e.g., expansion, shear, trapped surfaces).",
      "Demonstration that the swarm system satisfies the conjecture's assumptions (energy conditions, asymptotic flatness, etc.) or an explicit statement of which assumptions are relaxed.",
      "Independent verification using at least two methods (e.g., numerical relativity and invariant diagnostics).",
      "Proof that apparent support is not an artifact of finite resolution, gauge, or boundary conditions.",
      "Peer-reviewed, reproducible analysis with code/data availability."
    ],
    "for_refutation": [
      "An explicit, physically admissible counterexample: a solution to Einstein's equations (or controlled approximation) with a naked singularity.",
      "Proof that all energy conditions required by the conjecture hold (or a clear statement of which are violated and why that matters).",
      "Demonstration that the singularity is not a coordinate artifact (invariant curvature divergence).",
      "Evidence that the initial data are in the allowed class and that the evolution is stable under perturbations.",
      "Independent replication and convergence tests.",
      "A clear statement of which formulation is refuted and why other formulations are unaffected."
    ],
    "general": [
      "Pre-registration of predictions and analysis pipeline.",
      "Blinded analysis where possible.",
      "Quantified uncertainties and systematic error budget.",
      "Falsifiable predictions that distinguish support from refutation.",
      "Explicit limitations and scope of inference."
    ]
  },
  "gate_checklist": [
    {
      "gate": "G1",
      "question": "Is the specific cosmic censorship formulation stated precisely?",
      "pass_condition": "Weak/strong, matter model, initial data class, and energy conditions are explicitly defined.",
      "fail_action": "Reject claim as ill-posed."
    },
    {
      "gate": "G2",
      "question": "Are swarm observables rigorously mapped to covariant spacetime quantities?",
      "pass_condition": "A derivation or explicit protocol shows how agent data reconstruct horizon/trapped surface/singularity diagnostics.",
      "fail_action": "Reject as category error (CE2, CE6)."
    },
    {
      "gate": "G3",
      "question": "Does the system satisfy the conjecture's assumptions?",
      "pass_condition": "Energy conditions, asymptotic structure, and matter model are verified or deviations are explicitly justified.",
      "fail_action": "Claim is about a different conjecture; relabel or reject."
    },
    {
      "gate": "G4",
      "question": "Are artifacts ruled out?",
      "pass_condition": "Convergence tests, invariant diagnostics, gauge independence, and boundary condition checks are provided.",
      "fail_action": "Classify as false positive (FP1, FP4)."
    },
    {
      "gate": "G5",
      "question": "Is there independent replication?",
      "pass_condition": "At least two independent methods or groups reproduce the result.",
      "fail_action": "Downgrade evidence grade; do not claim support/refutation."
    },
    {
      "gate": "G6",
      "question": "Is the inference scoped correctly?",
      "pass_condition": "Claim explicitly states which formulation is addressed and does not overgeneralize.",
      "fail_action": "Reject overclaim; require rewrite."
    },
    {
      "gate": "G7",
      "question": "Are data/code and analysis available for scrutiny?",
      "pass_condition": "Reproducibility package is provided.",
      "fail_action": "Cap evidence grade at C."
    },
    {
      "gate": "G8",
      "question": "Are alternative explanations exhausted?",
      "pass_condition": "Null tests, systematic error budget, and competing hypotheses are addressed.",
      "fail_action": "Classify as false positive or inconclusive."
    }
  ],
  "evidence_grades": {
    "A": {
      "label": "Definitive",
      "criteria": [
        "All gates G1-G8 passed.",
        "For support: rigorous mapping, assumption verification, artifact exclusion, independent replication, and peer-reviewed reproducibility.",
        "For refutation: explicit physical counterexample with invariant singularity, energy condition verification, stability, and independent replication.",
        "Scope precisely limited to the stated formulation."
      ],
      "allowed_claims": [
        "Supports weak cosmic censorship for matter model X under assumptions Y.",
        "Refutes weak cosmic censorship for matter model X under assumptions Y."
      ]
    },
    "B": {
      "label": "Strong",
      "criteria": [
        "G1-G6 passed; G7 or G8 partially unmet.",
        "Independent replication present but limited.",
        "Artifacts largely ruled out but not exhaustively.",
        "Scope correctly limited."
      ],
      "allowed_claims": [
        "Provides strong evidence for/against a specific formulation, pending further verification."
      ]
    },
    "C": {
      "label": "Suggestive",
      "criteria": [
        "G1-G4 passed; G5-G8 unmet or weak.",
        "No independent replication.",
        "Artifact exclusion incomplete.",
        "Reproducibility limited."
      ],
      "allowed_claims": [
        "Motivates further study; does not support or refute cosmic censorship."
      ]
    },
    "D": {
      "label": "Inadmissible",
      "criteria": [
        "Any of G1-G4 failed.",
        "Category error present (CE1-CE8).",
        "False positive not ruled out (FP1-FP7).",
        "Overgeneralized claim."
      ],
      "allowed_claims": [
        "No claim about cosmic censorship permitted."
      ]
    }
  },
  "adversarial_notes": [
    "The burden of proof is on the claimant: absence of evidence for a horizon is not evidence for a naked singularity.",
    "Swarm studies may be useful for exploring analogue models or numerical methods, but they cannot by themselves confirm or refute a mathematical conjecture about general relativity.",
    "Any claim of refutation must survive the strongest known singularity theorems and energy condition analyses.",
    "Beware of 'swarm washing': using complex collective behavior to obscure weak physical foundations.",
    "Require explicit statements of what would count as falsification before accepting any result."
  ]
}
